package main
import("fmt";"os";"math";"github.com/shivang991/DashDevil2D/apps/server/configuration";"github.com/shivang991/DashDevil2D/apps/server/protocol";"github.com/shivang991/DashDevil2D/apps/server/simulation")
func main(){d,_:=os.ReadFile("../../packages/contracts/configuration/defaults.json");ids:=[2]protocol.Identity{{RoomId:1,SeatSession:11,PairGeneration:1,Seat:0},{RoomId:1,SeatSession:22,PairGeneration:1,Seat:1}};c,e:=configuration.Capture(d,"road-rage",nil);if e!=nil{panic(e)};g,_:=simulation.New(c,1,ids,1);in:=protocol.Input{Identity:ids[0],Round:protocol.Round{RoundId:1,InputGeneration:1},Sequence:1};if ok,_:=g.Submit(ids[0],in);ok{panic("malformed admitted")};in.Control=3;in.HeldMask=4;if ok,_:=g.Submit(ids[0],in);!ok{panic("valid sequence consumed")};g.AdvanceTo(.5);for i:=1;i<20;i++{in.Sequence=uint32(i+1);in.Intent=2;if ok,_:=g.Submit(ids[0],in);!ok{panic("refresh rejected")};if _,err:=g.AdvanceTo(float64(i+1)/2);err!=nil{panic(err)}};s:=g.Snapshot();want:=[]float64{4000,4400,4800,8000,8400,8800};if len(s.Track.Slices)!=len(want){panic("wrong windows")};for i,v:=range s.Track.Slices{if v.Distance!=want[i]{panic("wrong anchor")}};if math.Abs(s.Cars[0].Progress-8000)>1e-6||math.Abs(s.Cars[1].Progress-4000)>1e-6{panic("wrong distance")};fmt.Println("PASS malformed semantic admission, preserved sequence and six exact disjoint-window anchors",s.Cars[0].Progress,s.Cars[1].Progress,s.Track.RandomIndex,s.Track.NextID)}
